// People and the daily contest, as data: site/contributors/<id>.json (the owner and the house
// personas) and site/contest/days/<date>.json (one per contest day, generated by the engine's
// `fe content contest`). Checked here, so a bad file fails the build, and rendered by
// site/pages/people.mjs and site/pages/contest.mjs. Avatars are 32 × 32 letter grids drawn with
// the Board UI tokens only (AVATAR_PALETTE), one <path> per color.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { contributors as galleryContributors } from "./gallery.mjs";

const DAYS = "site/contest/days";
const NEED = ["id", "name", "role", "bio", "description", "kind", "style", "hobbies", "favoriteGames", "avatar"];
/** The house persona line: every persona's card and page says it, word for word. */
export const PERSONA_NOTE = "House persona — a Fizlet character, not a real person";
/** Contest rules the data must keep (and the page states). */
export const CONTEST = { maxPrompt: 60, minEntries: 12 };

/** Avatar letters → Board UI tokens (fixed colors, so a sprite reads the same in both themes). */
export const AVATAR_PALETTE = {
  k: "--rim", w: "--k-flag", c: "--k-sys", p: "--k-cmd", v: "--k-cmd-ink", m: "--k-attack", o: "--k-advance",
  l: "--k-fallin", g: "--k-go", y: "--hurt", r: "--k-fire", a: "--k-aim", n: "--line", d: "--raised",
};

const read = (dir) => (existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith(".json")).sort() : [])
  .map((f) => ({ f, v: JSON.parse(readFileSync(`${dir}/${f}`, "utf8")) }));

/** A gallery entry's author id (a site/contributors/<id>.json). */
export const authorOf = (e) => e.author;

/** The contributors (scripts/gallery.mjs reads them), checked for a profile: the owner first, then the personas by name. */
export function contributors(dir) {
  const list = Object.values(galleryContributors(dir)).map((p) => {
    const f = `${p.id}.json`;
    for (const k of NEED) if (p[k] === undefined) throw new Error(`contributors/${f}: missing ${k}`);
    if (p.kind !== "owner" && p.kind !== "persona") throw new Error(`contributors/${f}: kind ${p.kind}`);
    if (p.kind === "persona" && (p.url || !p.handle)) throw new Error(`contributors/${f}: a persona has a handle and no url (no fake links)`);
    checkAvatar(p.avatar, `contributors/${f}`);
    return p;
  });
  if (list.filter((p) => p.kind === "owner").length !== 1) throw new Error("contributors: exactly one owner");
  return list.sort((a, b) => (a.kind === b.kind ? a.name.localeCompare(b.name) : a.kind === "owner" ? -1 : 1));
}

function checkAvatar(rows, where) {
  if (!Array.isArray(rows) || rows.length !== 32) throw new Error(`${where}: avatar is 32 rows`);
  for (const r of rows) {
    if (r.length !== 32) throw new Error(`${where}: avatar rows are 32 pixels`);
    for (const ch of r) if (ch !== "." && !AVATAR_PALETTE[ch]) throw new Error(`${where}: avatar color "${ch}" is not a token`);
  }
}

/**
 * The avatar as inline SVG: a token background, then one path per color (runs of a row as
 * `M x y h n v1 h-n z`). Crisp at any size: shape-rendering crispEdges, image-rendering pixelated.
 * `label`: its accessible name, or null for a decorative copy (aria-hidden).
 */
export function avatarSvg(rows, { size = 64, label = null } = {}) {
  const paths = {};
  rows.forEach((row, y) => {
    for (let x = 0; x < 32;) {
      const ch = row[x];
      let n = 1;
      while (x + n < 32 && row[x + n] === ch) n++;
      if (ch !== ".") paths[ch] = (paths[ch] ?? "") + `M${x} ${y}h${n}v1h-${n}z`;
      x += n;
    }
  });
  const a11y = label ? `role="img" aria-label="${label.replace(/&/g, "&amp;").replace(/"/g, "&quot;")}"` : 'aria-hidden="true"';
  return `<svg class="ppl-av" viewBox="0 0 32 32" width="${size}" height="${size}" ${a11y} shape-rendering="crispEdges"><rect width="32" height="32" fill="var(--surface)"/>` +
    Object.entries(paths).map(([ch, d]) => `<path fill="var(${AVATAR_PALETTE[ch]})" d="${d}"/>`).join("") + "</svg>";
}

/**
 * The contest days, checked against the gallery, oldest first. A day's entries are the gallery
 * entries stamped `contest: "<date>"`; its winner is one of them. Rules: prompt ≤ 60 characters,
 * one entry per person per day, a winner only once the day has at least 12 entries. `files`:
 * [{ f, v }] (file name, parsed JSON), read from site/contest/days by default.
 */
export function contestDays(gallery, people, files = read(DAYS)) {
  const ids = new Set(people.map((p) => p.id));
  const days = files.map(({ f, v: d }) => {
    for (const k of ["date", "theme", "brief", "status"]) if (d[k] === undefined) throw new Error(`contest/days/${f}: missing ${k}`);
    if (`${d.date}.json` !== f || !/^\d{4}-\d{2}-\d{2}$/.test(d.date)) throw new Error(`contest/days/${f}: date ${d.date}`);
    if (!["upcoming", "open", "judging", "closed"].includes(d.status)) throw new Error(`contest/days/${f}: status ${d.status}`);
    return { ...d, entries: [] };
  });
  const byDate = new Map(days.map((d) => [d.date, d]));
  for (const e of gallery) {
    const a = authorOf(e);
    if (a && !ids.has(a)) throw new Error(`gallery/${e.id}: author ${a} has no site/contributors/${a}.json`);
    if (!e.contest) continue;
    const d = byDate.get(e.contest);
    if (!d) throw new Error(`gallery/${e.id}: contest ${e.contest} has no site/contest/days/${e.contest}.json`);
    if (e.prompt.length > CONTEST.maxPrompt) throw new Error(`gallery/${e.id}: a contest prompt is ${CONTEST.maxPrompt} characters at most (${e.prompt.length})`);
    if (d.entries.some((x) => authorOf(x) === a)) throw new Error(`gallery/${e.id}: one entry per person per day (${a} on ${d.date})`);
    d.entries.push(e);
  }
  for (const d of days) {
    if (!d.winner) continue;
    if (!d.entries.some((e) => e.id === d.winner)) throw new Error(`contest/days/${d.date}.json: winner ${d.winner} is not one of its entries`);
    if (d.entries.length < CONTEST.minEntries) throw new Error(`contest/days/${d.date}.json: a winner needs at least ${CONTEST.minEntries} entries (${d.entries.length})`);
  }
  return days.sort((a, b) => a.date.localeCompare(b.date));
}

/** The day the contest page leads with: today's, else the next one, else the latest. */
export function contestToday(days, today = new Date().toISOString().slice(0, 10)) {
  return days.find((d) => d.date === today) ?? days.find((d) => d.date > today) ?? days[days.length - 1] ?? null;
}

/** A contributor's gallery entries (newest first, as the gallery orders them) and their measured bytes. */
export function statsOf(person, gallery) {
  const entries = gallery.filter((e) => authorOf(e) === person.id);
  return { entries, count: entries.length, bytes: entries.reduce((n, e) => n + e.size, 0) };
}
